changeSet.sql:
ALTER TABLE item_object
    ADD CONSTRAINT ck_item_object_impact_non_negative CHECK (impact >= 0);
ALTER TABLE item
    ADD CONSTRAINT ck_item_enhance_level_non_negative CHECK (enhance_level >= 0),
    ADD CONSTRAINT ck_item_enhance_revision_non_negative CHECK (enhance_revision >= 0);
ALTER TABLE personage
    ADD CONSTRAINT ck_personage_storm_shards_non_negative CHECK (storm_shards >= 0);
